const puppeteer=require('puppeteer-core');
const fs=require('fs');
const path=require('path');
(async()=>{
  const times=(process.argv[2]||'0.5,2.5,5.5,8.5,12.5,15.5,19.5,22.5,26.5,29.2').split(',').map(Number);
  const out=process.argv[3]||'build/stills';
  fs.mkdirSync(out,{recursive:true});
  const browser=await puppeteer.launch({executablePath:'/usr/bin/google-chrome',headless:'new',args:['--no-sandbox','--disable-gpu','--hide-scrollbars','--force-device-scale-factor=1','--font-render-hinting=none']});
  const page=await browser.newPage();
  page.on('console',m=>console.log('PAGE',m.type(),m.text()));
  page.on('pageerror',e=>console.log('PAGEERROR',e.message));
  await page.setViewport({width:1920,height:1080,deviceScaleFactor:1});
  await page.goto('file://'+path.resolve('src/scene.html'),{waitUntil:'load'});
  await page.waitForFunction('window.__ready===true');
  for(const t of times){
    await page.evaluate(tt=>window.renderAt(tt),t);
    const data=await page.evaluate(()=>document.getElementById('c').toDataURL('image/png'));
    fs.writeFileSync(path.join(out,`t${t.toFixed(2).padStart(5,'0')}.png`),Buffer.from(data.split(',')[1],'base64'));
    console.log('wrote',t);
  }
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
